begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(32);
insert into public.clinics(id,name) values('e1000000-0000-4000-8000-000000000001','Synthetic Search A'),('e1000000-0000-4000-8000-000000000002','Synthetic Search B');
insert into auth.users(id) values('e2000000-0000-4000-8000-000000000001'),('e2000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','reception',true),('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000002','manager',true);
select set_config('request.jwt.claim.sub','e2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
create function pg_temp.search(name text) returns jsonb language sql as $$select public.inquiry_owner_search_page('e1000000-0000-4000-8000-000000000001',jsonb_build_object('name',name,'before',null))$$;
select ok(not has_function_privilege('anon','public.inquiry_owner_search_page(uuid,jsonb)','EXECUTE'),'anonymous execution denied');
select is((select enabled from private.intake_command_settings),false,'writes disabled');
set local role authenticated;
select is(jsonb_array_length(pg_temp.search('Missing')->'items'),0,'empty search works while disabled');
select throws_ok($$select public.inquiry_owner_search_page('e1000000-0000-4000-8000-000000000002','{"name":"Synthetic"}')$$,'42501',null,'cross-clinic denied');
select throws_ok($$select pg_temp.search(' Synthetic ')$$,'22023',null,'reject noncanonical edges');
select throws_ok($$select pg_temp.search('S')$$,'22023',null,'minimum2');
select throws_ok($$select pg_temp.search(E'Sy\tnthetic')$$,'22023',null,'controls rejected');
select throws_ok($$select pg_temp.search(repeat('😀',81))$$,'22023',null,'maximum80 Unicode points');
reset role;
insert into public.inquiries(clinic_id,owner_user_id,display_name,source) values
('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',E'Synthetic \\%_','phone'),
('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Synthetic decoy','phone'),
('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Cafe','phone'),
('e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Café','phone');
select is(jsonb_array_length(pg_temp.search(E'\\%_')->'items'),1,'backslash and wildcards literal');
select is(jsonb_array_length(pg_temp.search('sYnThEtIc')->'items'),2,'ASCII case insensitive');
select is(jsonb_array_length(pg_temp.search('Cafe')->'items'),1,'accent not folded in local database');
select is(jsonb_array_length(pg_temp.search('CAFÉ')->'items'),(select count(*)::int from public.inquiries where clinic_id='e1000000-0000-4000-8000-000000000001' and owner_user_id='e2000000-0000-4000-8000-000000000001' and display_name ilike '%CAFÉ%'),'actual database Unicode case semantics');
insert into public.inquiries(clinic_id,owner_user_id,display_name,source) select 'e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000002','Needle','phone' from generate_series(1,101);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source,created_at) values('e3000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Needle','phone','2000-01-01Z');
select is(jsonb_array_length(pg_temp.search('Needle')->'items'),1,'owner filter before limit');
select is((select count(*)::int from jsonb_object_keys(pg_temp.search('Needle')->'items'->0)),6,'minimal summary');
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source,created_at) select ('e4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'e1000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Needle','phone','2026-10-26T20:00:00.123456Z' from generate_series(1,50)n;
select is(jsonb_array_length(pg_temp.search('Needle')->'items'),50,'bounded50');
select is((pg_temp.search('Needle')->>'truncated')::boolean,true,'51 explicitly partial');
select is(pg_temp.search('Needle')->'items'->0->>'id','e4000000-0000-4000-8000-000000000050','private DB UUID ordering preserved');
select is(pg_temp.search('Needle')->>'name','Needle','exact query echoed');
select is(pg_temp.search('Needle')->'before','null'::jsonb,'first bound echoed');
select is(pg_temp.search('Needle')->'next_before',jsonb_build_object('created_at',pg_temp.search('Needle')->'items'->49->'created_at','inquiry_id',pg_temp.search('Needle')->'items'->49->'id'),'continuation equals last returned tuple');
create function pg_temp.page(bound jsonb) returns jsonb language sql as $$select public.inquiry_owner_search_page('e1000000-0000-4000-8000-000000000001',jsonb_build_object('name','Needle','before',bound))$$;
select is(jsonb_array_length(pg_temp.page(pg_temp.search('Needle')->'next_before')->'items'),1,'bound applied before limit');
select is(pg_temp.page(pg_temp.search('Needle')->'next_before')->'next_before','null'::jsonb,'final page has no continuation');
select is(jsonb_array_length(pg_temp.page('{"created_at":"0001-01-01T00:00:00Z","inquiry_id":"e3000000-0000-4000-8000-000000000099"}')->'items'),0,'fabricated cursor harmless empty result');
select is(pg_temp.page('{"created_at":"2026-10-26T21:00:00.123456+01:00","inquiry_id":"e4000000-0000-4000-8000-000000000003"}')->'before','{"created_at":"2026-10-26T21:00:00.123456+01:00","inquiry_id":"e4000000-0000-4000-8000-000000000003"}'::jsonb,'exact offset bound echoed');
select is(pg_temp.page('{"created_at":"2026-10-26T21:00:00.123456+01:00","inquiry_id":"e4000000-0000-4000-8000-000000000003"}')->'items'->0->>'id','e4000000-0000-4000-8000-000000000002','equal timestamp compares native UUID strictly');
select throws_ok($$select pg_temp.page('{"created_at":"2026-10-26T20:00:00.1234567Z","inquiry_id":"e4000000-0000-4000-8000-000000000003"}')$$,'22023',null,'reject precision loss');
select throws_ok($$select pg_temp.page('{"created_at":"0001-01-01T00:00:00+01:00","inquiry_id":"e4000000-0000-4000-8000-000000000003"}')$$,'22023',null,'reject UTC year overflow');
select throws_ok($$select pg_temp.page('{}')$$,'22023',null,'reject malformed bound');
select set_config('request.method','GET',true);
select throws_ok($$select pg_temp.search('Needle')$$,'22023',null,'direct GET denied');
select set_config('request.method','POST',true);
update public.clinic_memberships set role='assistant' where user_id='e2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.search('Needle')$$,'42501',null,'privileged assistant denied');
update public.clinic_memberships set role='reception',active=false where user_id='e2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.search('Needle')$$,'42501',null,'inactive owner denied');
select is((select count(*)::int from private.outbox_events where clinic_id='e1000000-0000-4000-8000-000000000001'),0,'no writes or events');
select * from finish();
rollback;
